package com.example.basicbrowser.variation.model

import com.example.basicbrowser.proxy.intercept.HttpRequestData

/**
 * Represents a single HTTP request generated by the Intruder engine for execution.
 *
 * @param index 1-based sequential request index (1..total).
 * @param request The prepared HttpRequestData with all markers substituted.
 * @param payloadSummary Text describing the payload or tuple tested in this request.
 * @param attackType The attack type used to produce this request.
 * @param activeInsertionPoint For Sniper mode: the specific insertion point being tested.
 */
data class GeneratedVariationRequest(
    val index: Int,
    val request: HttpRequestData,
    val payloadSummary: String,
    val attackType: AttackType,
    val activeInsertionPoint: InsertionPoint? = null
)

